def frame_items(leaf: bytes) -> list:
    items = []
    offset = 0
    while offset < len(leaf):
        length = int.from_bytes(leaf[offset:offset + 4], "big")
        offset += 4
        items.append(leaf[offset:offset + length])
        offset += length
    return items


